const raw = $input.item.json.body ?? $input.item.json;

const origemMap = {
  whatsapp: 'whatsapp',
  lovable: 'lovable',
  instagram: 'instagram_futuro',
  loja: 'atendimento_loja'
};
const origem_lead = origemMap[raw.canal] ?? 'whatsapp';

const history = (raw.contexto ?? [])
  .filter(m => m.tipo !== 'interno')
  .slice(-10)
  .map(m => ({
    role: m.tipo === 'cliente' ? 'cliente' : m.tipo === 'bia' ? 'bia' : 'atendente',
    text: m.texto,
    at: m.criadoEm
  }));

const is_first_contact = history.filter(m => m.role === 'cliente').length <= 1;

let pre_qualified = { uso_principal: null, orcamento: null, estado: null, prioridade: null };
if (origem_lead === 'lovable') {
  try {
    const pq = JSON.parse(raw.mensagemCliente);
    pre_qualified = {
      uso_principal: pq.uso_principal ?? null,
      orcamento: pq.orcamento ?? null,
      estado: pq.estado ?? null,
      prioridade: pq.prioridade ?? null
    };
  } catch (_) {}
}

return {
  json: {
    lead_id: raw.leadId,
    lead_nome: raw.leadNome ?? null,
    origem_lead,
    current_message: raw.mensagemCliente,
    resumo: raw.resumo ?? null,
    is_first_contact,
    history,
    pre_qualified
  }
};

const j = $input.item.json;

const hist = (j.history ?? [])
  .map(m => `[${m.role}]: ${m.text}`)
  .join('\n') || '(sem histórico)';

const pqLines = j.origem_lead === 'lovable'
  ? `Uso principal: ${j.pre_qualified.uso_principal ?? '-'}\nOrçamento: ${j.pre_qualified.orcamento ?? '-'}\nEstado: ${j.pre_qualified.estado ?? '-'}\nPrioridade: ${j.pre_qualified.prioridade ?? '-'}`
  : 'N/A (lead whatsapp — coletar durante conversa)';

const prompt = [
  `ORIGEM: ${j.origem_lead}`,
  `LEAD: ${j.lead_nome ?? 'não identificado'}`,
  `PRIMEIRO CONTATO: ${j.is_first_contact ? 'sim' : 'não'}`,
  `RESUMO ANTERIOR: ${j.resumo ?? 'nenhum'}`,
  '',
  'HISTÓRICO (últimas 10 msgs):',
  hist,
  '',
  'PRÉ-QUALIFICAÇÃO:',
  pqLines,
  '',
  'MENSAGEM ATUAL DO CLIENTE:',
  j.current_message
].join('\n');

return {
  json: {
    ...j,
    prompt
  }
};

const raw = $input.item.json;
const classificacao = raw.output ?? raw;
const normalizado = $('normalizar_entrada').item.json;

const blacklist = [
  'em estoque', 'disponível', 'temos disponível', 'tenho aqui',
  'saúde da bateria', 'bateria está', 'capacidade da bateria',
  'desconto', 'promoção especial', 'condição especial',
  'reservado', 'posso reservar', 'vou reservar',
  'garanto', 'confirmo disponibilidade'
];

let response_text = classificacao.response_text ?? 'Nosso time de vendas pode te ajudar! Posso conectar você agora?';
let humano = classificacao.humano ?? false;
let handoff_reason = null;

const lower = response_text.toLowerCase();
if (blacklist.some(kw => lower.includes(kw))) {
  response_text = 'Nosso time de vendas tem todas as informações atualizadas. Posso te conectar com eles agora?';
  humano = true;
  handoff_reason = 'violation_blacklist';
}

return {
  json: {
    crm_payload: {
      lead_id: normalizado.lead_id,
      respostas: [{ texto: response_text, mediaUrl: null }],
      metadata: {
        intencao: classificacao.intencao ?? 'outro',
        complexidade: classificacao.complexidade ?? 'simples',
        lead_score: classificacao.lead_score ?? 0,
        urgencia: classificacao.urgencia ?? 'baixa',
        estado_atendimento: classificacao.estado_atendimento ?? 'qualificando',
        origem_lead: normalizado.origem_lead,
        resumo: classificacao.resumo ?? null,
        humano,
        handoff_reason
      }
    }
  }
};
